//! `InchiToMol` (`inchi_to_mol.rs`): InChI -> molecule -> InChI round trips
//! over the corpus of InChI strings generated by the C library, and a few
//! known SMILES.

use rdoxide::external::inchi_api::{ExtraInchiReturnValues, inchi_to_mol, mol_to_inchi};
use rdoxide::graphmol::smiles_parse::write::{SmilesWriteParams, mol_to_smiles};

#[test]
fn known_structures() {
    let cases = [
        ("InChI=1S/CH4/h1H4", "C"),
        ("InChI=1S/C2H6O/c1-2-3/h3H,2H2,1H3", "CCO"),
        ("InChI=1S/C6H6/c1-2-4-6-5-3-1/h1-6H", "c1ccccc1"),
        ("InChI=1S/C4H8/c1-3-4-2/h3-4H,1-2H3/b4-3+", "C/C=C/C"),
        (
            "InChI=1S/C3H7NO2/c1-2(4)3(5)6/h2H,4H2,1H3,(H,5,6)/t2-/m0/s1",
            "C[C@H](N)C(=O)O",
        ),
        ("InChI=1S/ClHO4/c2-1(3,4)5/h(H,2,3,4,5)", "O=Cl(=O)(=O)O"),
    ];
    for (inchi, want) in cases {
        let mut rv = ExtraInchiReturnValues::default();
        let mut m = inchi_to_mol(inchi, &mut rv, true, true).unwrap().unwrap();
        let smi = mol_to_smiles(&mut m, &SmilesWriteParams::default()).unwrap();
        assert_eq!(
            smi,
            want.replace("O=Cl(=O)(=O)O", "[O-][Cl+3]([O-])([O-])O"),
            "{inchi}"
        );
    }
}

#[test]
fn round_trip_corpus() {
    let text = include_str!("../../../tests/data/inchi_corpus.jsonl");
    let (mut n, mut same, mut none) = (0, 0, 0);
    let mut bad = Vec::new();
    for line in text.lines() {
        let v: serde_json::Value = serde_json::from_str(line).unwrap();
        if v["kind"] != "mol" || v["retcode"].as_i64().unwrap() > 1 {
            continue;
        }
        let inchi = v["inchi"].as_str().unwrap();
        if !inchi.starts_with("InChI=1") || inchi.contains("/o") || inchi.contains("/z") {
            continue;
        }
        n += 1;
        let mut rv = ExtraInchiReturnValues::default();
        let m = match inchi_to_mol(inchi, &mut rv, true, true) {
            Ok(Some(m)) => m,
            Ok(None) => {
                none += 1;
                bad.push(format!("{inchi}: none {} {}", rv.return_code, rv.message));
                continue;
            }
            Err(e) => {
                bad.push(format!("{inchi}: {e}"));
                continue;
            }
        };
        let mut rv2 = ExtraInchiReturnValues::default();
        let back = mol_to_inchi(&m, &mut rv2, None).unwrap();
        // the standard InChI of the restored molecule has no fixed-H layer
        let want = match inchi.strip_prefix("InChI=1/") {
            Some(rest) => format!("InChI=1S/{}", rest.split("/f").next().unwrap()),
            None => inchi.to_string(),
        };
        if back == want {
            same += 1;
        } else {
            bad.push(format!("{inchi} -> {back}"));
        }
    }
    eprintln!("{same}/{n} identical, {none} none");
    for b in bad.iter().take(80) {
        eprintln!("  {b}");
    }
    assert!(same * 10 >= n * 9, "too many round-trip differences");
}
